import { call } from "../abi.ts";
import type { ArgOption, Completion, UiRequest } from "../types/index.ts";

type Op = UiRequest["op"];

const ask = <R>(op: Op, args?: object): R => call<R>({ op, args });

/** `/complete`'s whole lines as one field's options: the prefix sliced back off, deduped, labels kept. */
export const optionsFromCompletions = (
  full: ReadonlyArray<Completion>,
  prefix: string,
): ArgOption[] => ask("ui.options_from_completions", { full, prefix });

/** The line's arguments, trailing blanks dropped; a blank in the middle is kept. */
export const lineArgs = (values: ReadonlyArray<string>): string[] =>
  ask("ui.line_args", { values });
